const fecha = $('Fecha objetivo').first().json.fecha;
const norm = v => {
  if (typeof v === 'number') return DateTime.fromMillis(Math.round((v - 25569) * 86400000), { zone: 'utc' }).toFormat('yyyy-MM-dd');
  const s = String(v || '').trim();
  let d = DateTime.fromISO(s);
  if (!d.isValid) d = DateTime.fromFormat(s, 'd/M/yyyy');
  return d.isValid ? d.toFormat('yyyy-MM-dd') : s;
};
const filas = $input.all().map(i => i.json)
  .filter(r => r.producto && norm(r.fecha_entrega) === fecha && String(r.estado || '').toLowerCase() === 'aceptado');
const titulo = DateTime.fromISO(fecha).setLocale('es').toFormat('cccc dd/MM');
const th = 'style="border:1px solid #555;padding:6px 10px;background:#c9daf8"';
const td = 'style="border:1px solid #555;padding:6px 10px"';
const tc = 'style="border:1px solid #555;padding:6px 10px;text-align:center"';
const tt = 'style="border:1px solid #555;padding:6px 10px;text-align:center;font-weight:bold;background:#d9d9d9"';

const secciones = [['Panadería', ['Panadería', 'Sandwiches']], ['Pastelería', ['Pastelería']]];
return secciones.map(([nombre, incluye]) => {
  const fs = filas.filter(r => incluye.includes(r.seccion));
  const clientes = [...new Set(fs.map(r => r.cliente))].sort();
  const prods = {};
  for (const r of fs) {
    const p = prods[r.producto] ??= { producto: r.producto, porCliente: {}, total: 0, obs: new Set() };
    const c = Number(r.cantidad) || 0;
    p.porCliente[r.cliente] = (p.porCliente[r.cliente] || 0) + c;
    p.total += c;
    if (r.observacion) p.obs.add(r.observacion);
  }
  const lista = Object.values(prods).sort((a, b) => a.producto.localeCompare(b.producto, 'es'));
  const html = !lista.length ? `<p>No hay pedidos de ${nombre} para el ${titulo}.</p>` :
    `<table style="border-collapse:collapse;font-family:Arial;font-size:14px">
     <tr><th colspan="${clientes.length + 3}" ${th}>${nombre.toUpperCase()}</th></tr>
     <tr><td ${th}>FECHA</td><th colspan="${clientes.length + 1}" ${th}>${titulo}</th><td ${th}></td></tr>
     <tr><td ${th}></td>${clientes.map(c => `<td ${th}>${c}</td>`).join('')}<th ${th}>Total</th><th ${th}>Observación</th></tr>
     ${lista.map(p => `<tr><td ${td}>${p.producto}</td>${clientes.map(c => `<td ${tc}>${p.porCliente[c] ?? ''}</td>`).join('')}<td ${tt}>${p.total}</td><td ${tc}>${[...p.obs].join(', ') || '-'}</td></tr>`).join('')}
     </table>`;
  return { json: { seccion: nombre, fecha, productos: lista.length, asunto: `Planilla de ${nombre} – ${titulo}`, html } };
});
